              split-point)))
      (lambda (frame)
        (paint-upper frame)
        (paint-lower frame)))))


function below(painter1, painter2) {
    const split_point = make_vect(0, 0.5);
    const paint_upper =
        transform_painter(painter1,
                          split_point,
                          make_vect(1, 0.5),
                          make_vect(0, 1));
    const paint_lower =
        transform_painter(painter2,
                          make_vect(0, 0),
                          make_vect(1, 0),
                          split_point);
    return frame => {
               paint_upper(frame);
               paint_lower(frame);
           };
}



